namespace Steamworks {
 public enum EResult{k_EResultOK,k_EResultFail} public enum ELobbyType{k_ELobbyTypePrivate,k_ELobbyTypeFriendsOnly}
 public enum ESteamNetworkingConnectionState{k_ESteamNetworkingConnectionState_Connecting,k_ESteamNetworkingConnectionState_Connected,k_ESteamNetworkingConnectionState_ClosedByPeer,k_ESteamNetworkingConnectionState_ProblemDetectedLocally}
 public enum ESteamNetworkingConfigValue{k_ESteamNetworkingConfig_P2P_Transport_ICE_Enable}public enum ESteamNetworkingConfigDataType{k_ESteamNetworkingConfig_Int32}
 public struct SteamNetworkingConfigValue_t{public ESteamNetworkingConfigValue m_eValue;public ESteamNetworkingConfigDataType m_eDataType;public OptionValue m_val;public struct OptionValue{public int m_int32;}}
 public struct CSteamID{public ulong m_SteamID;public CSteamID(ulong n){m_SteamID=n;}public bool IsLobby(){return m_SteamID>=100;}public override string ToString(){return m_SteamID.ToString();}public static bool operator ==(CSteamID a,CSteamID b){return a.m_SteamID==b.m_SteamID;}public static bool operator !=(CSteamID a,CSteamID b){return !(a==b);}public override bool Equals(object o){return o is CSteamID&&this==(CSteamID)o;}public override int GetHashCode(){return m_SteamID.GetHashCode();}}
 public struct HSteamListenSocket{public uint m_HSteamListenSocket;public static bool operator ==(HSteamListenSocket a,HSteamListenSocket b){return a.m_HSteamListenSocket==b.m_HSteamListenSocket;}public static bool operator !=(HSteamListenSocket a,HSteamListenSocket b){return !(a==b);}public override bool Equals(object o){return o is HSteamListenSocket&&this==(HSteamListenSocket)o;}public override int GetHashCode(){return (int)m_HSteamListenSocket;}}
 public struct HSteamNetConnection{public uint m_HSteamNetConnection;public static bool operator ==(HSteamNetConnection a,HSteamNetConnection b){return a.m_HSteamNetConnection==b.m_HSteamNetConnection;}public static bool operator !=(HSteamNetConnection a,HSteamNetConnection b){return !(a==b);}public override bool Equals(object o){return o is HSteamNetConnection&&this==(HSteamNetConnection)o;}public override int GetHashCode(){return (int)m_HSteamNetConnection;}}
 public struct SteamNetworkingIdentity{public CSteamID id;public void SetSteamID(CSteamID x){id=x;}public CSteamID GetSteamID(){return id;}}
